    for (unsigned P : {1024u, 2048u, 4096u, 8192u}) {
        bench<0>(in, part, out, n, P); bench<1>(in, part, out, n, P); bench<2>(in, part, out, n, P); bench<3>(in, part, out, n, P);
    }
}
