    std::vector<uint32_t> h(n); for (size_t i = 0; i < n; ++i) h[i] = i % 7;
    tsr::DeviceBuffer<uint32_t> d, o(n); d.upload(h);
    tsr::Arena arena(1 << 20);
    tsr::prims::exclusive_scan(d.data(), o.data(), n, arena, nullptr);
    auto g = o.to_host();
    uint32_t acc = 0; size_t bad = 0, firstbad = n;
    for (size_t i = 0; i < n; ++i) { if (g[i] != acc) { if (!bad) firstbad = i; bad++; } acc += h[i]; }
    printf("n=%zu bad=%zu firstbad=%zu (expected %u got %u)\n", n, bad, firstbad, firstbad < n ? [&]{uint32_t a=0; for(size_t i=0;i<firstbad;++i)a+=h[i]; return a;}() : 0u, firstbad < n ? g[firstbad] : 0u);
    // partition boundaries: P = ceil(n/8192)
    unsigned P = (n + 8191) / 8192; if (P > 4096) P = 4096;
    uint64_t per = (n + P - 1) / P;
    for (unsigned p = 0; p < P && p < 12; ++p) { size_t b = p * per; if (b < n) printf("  p=%u begin=%zu got=%u exp=%u\n", p, b, g[b], [&]{uint32_t a=0; for(size_t i=0;i<b;++i)a+=h[i]; return a;}()); }
}
