template<typename T>
inline T scan_A(T value, T *s_vals, T *s_seg, unsigned tid, unsigned nth, T &total)
{
    const unsigned nseg    = nth < kScanSegments ? nth : kScanSegments;
    const unsigned seg_len = (nth + nseg - 1) / nseg;
    s_vals[tid]            = value;
#pragma omp barrier
