    {
        const unsigned lo = tid * seg_len;
        const unsigned hi = lo + seg_len < nth ? lo + seg_len : nth;
        T sum             = T(0);
#pragma unroll 1
        for(unsigned i = lo; i < hi; ++i) sum += s_vals[i];
        s_seg[tid] = sum;
    }
#pragma omp barrier
    if(tid == 0)
    {
        T run = T(0);
#pragma unroll 1
        for(unsigned i = 0; i < nseg; ++i) { const T c = s_seg[i]; s_seg[i] = run; run += c; }
        s_seg[kScanSegments] = run;
    }
#pragma omp barrier
    if(tid < nseg)
    {
        const unsigned lo = tid * seg_len;
        const unsigned hi = lo + seg_len < nth ? lo + seg_len : nth;
        T run             = s_seg[tid];
#pragma unroll 1
        for(unsigned i = lo; i < hi; ++i) { const T c = s_vals[i]; s_vals[i] = run; run += c; }
    }
#pragma omp barrier
    const T result = s_vals[tid];
    total          = s_seg[kScanSegments];
#pragma omp barrier
    return result;
}

// Variant B: Hillis-Steele double buffered. s_vals must hold 2*kMaxThreads.
template<typename T>
inline T scan_B(T value, T *s_vals, unsigned tid, unsigned nth, T &total)
{
    unsigned buf = 0;
    s_vals[tid] = value;
#pragma omp barrier
    for(unsigned offset = 1; offset < nth; offset <<= 1)
    {
        T v = s_vals[buf * kMaxThreads + tid];
        if(tid >= offset) v += s_vals[buf * kMaxThreads + tid - offset];
        buf ^= 1u;
        s_vals[buf * kMaxThreads + tid] = v;
#pragma omp barrier
    }
    const T incl = s_vals[buf * kMaxThreads + tid];
    total = s_vals[buf * kMaxThreads + nth - 1];
#pragma omp barrier
    return incl - value;
}

template<typename T, unsigned ITEMS, int VARIANT>
void scan_downsweep(const T *in, T *out, const T *totals, std::uint64_t n, unsigned P, bool inclusive)
{
#pragma omp target teams num_teams(P) thread_limit(kMaxThreads) is_device_ptr(in, out, totals)
    {
        T s_vals[2 * kMaxThreads];
        T s_seg[kScanSegments + 1];
#pragma omp parallel
        {
            const TeamInfo ti = this_team();
            for(unsigned p = ti.team; p < P; p += ti.nteams)
            {
                std::uint64_t begin, end;
                partition_range(n, p, P, begin, end);
                T carry                   = totals[p];
                const std::uint64_t chunk = static_cast<std::uint64_t>(ti.nth) * ITEMS;
                for(std::uint64_t cb = begin; cb < end; cb += chunk)
                {
                    const std::uint64_t i0 = cb + static_cast<std::uint64_t>(ti.tid) * ITEMS;
                    T items[ITEMS];
                    T incl[ITEMS];
#pragma unroll
                    for(unsigned k = 0; k < ITEMS; ++k)
                    {
                        items[k] = i0 + k < end ? in[i0 + k] : T(0);
                        incl[k]  = k == 0 ? items[0] : incl[k - 1] + items[k];
                    }
                    T total; T excl;
                    if constexpr (VARIANT == 0) excl = team_exclusive_scan(incl[ITEMS - 1], s_vals, s_seg, ti.tid, ti.nth, total);
                    else if constexpr (VARIANT == 1) excl = scan_A(incl[ITEMS - 1], s_vals, s_seg, ti.tid, ti.nth, total);
                    else excl = scan_B(incl[ITEMS - 1], s_vals, ti.tid, ti.nth, total);
                    const T base = carry + excl;
#pragma unroll
                    for(unsigned k = 0; k < ITEMS; ++k)
                    {
                        if(i0 + k < end)
                        {
                            out[i0 + k] = inclusive ? base + incl[k] : (k == 0 ? base : base + incl[k - 1]);
                        }
                    }
                    carry += total;
                }
            }
        }
    }
}

template<unsigned ITEMS, int V> void bench(const uint32_t* in, uint32_t* out, uint32_t* tot, size_t n, unsigned P, bool incl) {
    scan_downsweep<uint32_t, ITEMS, V>(in, out, tot, n, P, incl);
    std::vector<double> t;
    for (int r = 0; r < 9; ++r) { auto a = clk::now(); scan_downsweep<uint32_t, ITEMS, V>(in, out, tot, n, P, incl); auto b = clk::now(); t.push_back(std::chrono::duration<double, std::micro>(b-a).count()); }
