    std::vector<uint32_t> h(n); omp_target_memcpy(h.data(), out, n * 4, 0, 0, omp_get_initial_device(), omp_get_default_device());
    size_t bad = 0; uint32_t acc = 0; uint64_t per = (n + P - 1) / P;
    for (size_t i = 0; i < n; ++i) { if (i % per == 0) acc = 0; if (h[i] != acc) bad++; acc += 1; }
    printf("ITEMS=%u variant %d P=%u incl=%d: %.0f us (bad=%zu)\n", ITEMS, V, P, (int)incl, t[4], bad);
}

int main() {
    const size_t n = 1ull << 26;
