                        count_digit(digit_of(k3, shift, digit_mask), c0, c1, c2, c3);
                    }
                    for(; i < re; i += ti.nth)
                    {
                        count_digit(digit_of(keys[i], shift, digit_mask), c0, c1, c2, c3);
                    }
                    const std::uint32_t packed[4] = {c0, c1, c2, c3};
#pragma unroll
                    for(unsigned d = 0; d < kRadixDigits; ++d)
                    {
                        const std::uint32_t c = (packed[d >> 2] >> (8u * (d & 3u))) & 0xffu;
                        if(c != 0)
                        {
#pragma omp atomic update
                            s_hist[d] += c;
                        }
                    }
                }
#pragma omp barrier
                for(unsigned d = ti.tid; d < kRadixDigits; d += ti.nth)
                {
                    counts[d * P + p] = s_hist[d];
                    publish_writes();
                }
#pragma omp barrier
            }
            if(team_is_last(0, ti.nteams, ti.tid, &s_flag))
            {
                const unsigned total_counts = kRadixDigits * P;
                const unsigned per          = (total_counts + ti.nth - 1) / ti.nth;
