#include <chrono>
#include <cstdio>
#include <vector>
#include <algorithm>
#include "tsr/prims/team.h"
using namespace tsr::prims;
using clk = std::chrono::steady_clock;

template<typename T> struct alignas(16) Vec4 { T x, y, z, w; };

template<int VARIANT>
void reduce_kernel(const float *in, float *partials, float *out, std::uint64_t n, unsigned P)
{
#pragma omp target teams num_teams(P) thread_limit(256) is_device_ptr(in, partials, out)
    {
        float s_vals[256];
        unsigned s_flag;
#pragma omp parallel
        {
            const TeamInfo ti = this_team();
            const SumOp<float> op{};
            for(unsigned p = ti.team; p < P; p += ti.nteams)
            {
                std::uint64_t begin, end;
                partition_range(n, p, P, begin, end);
                float acc = 0;
                if constexpr (VARIANT == 0) {
                    std::uint64_t i = begin + ti.tid;
                    const std::uint64_t stride = static_cast<std::uint64_t>(ti.nth) * 4;
                    for(; i + 3 * ti.nth < end; i += stride) {
                        float v[4];
                        #pragma unroll
                        for (unsigned k = 0; k < 4; ++k) v[k] = in[i + k * ti.nth];
                        #pragma unroll
                        for (unsigned k = 0; k < 4; ++k) acc = op(acc, v[k]);
                    }
                    for(; i < end; i += ti.nth) acc = op(acc, in[i]);
                } else {
                    // vectorized: partition boundaries are multiples of 4 (host guarantees), pointer 16B aligned
                    const Vec4<float>* vin = reinterpret_cast<const Vec4<float>*>(in);
                    std::uint64_t vb = begin / 4, ve = end / 4;
                    std::uint64_t i = vb + ti.tid;
                    const std::uint64_t stride = static_cast<std::uint64_t>(ti.nth) * (VARIANT == 2 ? 2 : 1);
                    if constexpr (VARIANT == 2) {
                        for(; i + ti.nth < ve; i += stride) {
                            const Vec4<float> a = vin[i], b = vin[i + ti.nth];
                            acc += a.x; acc += a.y; acc += a.z; acc += a.w;
                            acc += b.x; acc += b.y; acc += b.z; acc += b.w;
                        }
                    }
                    for(; i < ve; i += ti.nth) { const Vec4<float> a = vin[i]; acc += a.x; acc += a.y; acc += a.z; acc += a.w; }
                    for (std::uint64_t j = ve * 4 + ti.tid; j < end; j += ti.nth) acc += in[j];
                }
                const float r = team_reduce(acc, op, s_vals, ti.tid, ti.nth);
                if(ti.tid == 0) { partials[p] = r; publish_writes(); }
            }
            if(team_is_last(0, ti.nteams, ti.tid, &s_flag))
            {
                float acc = 0;
                for(unsigned i = ti.tid; i < P; i += ti.nth) acc = op(acc, team_load(&partials[i]));
                const float r = team_reduce(acc, op, s_vals, ti.tid, ti.nth);
                if(ti.tid == 0) *out = r;
            }
        }
    }
}

template<int V> void bench(const float* in, float* part, float* out, size_t n, unsigned P) {
    reduce_kernel<V>(in, part, out, n, P);
    std::vector<double> t;
    for (int r = 0; r < 11; ++r) { auto a = clk::now(); reduce_kernel<V>(in, part, out, n, P); auto b = clk::now(); t.push_back(std::chrono::duration<double, std::micro>(b-a).count()); }
    std::sort(t.begin(), t.end());
    float h; omp_target_memcpy(&h, out, 4, 0, 0, omp_get_initial_device(), omp_get_default_device());
    printf("variant %d P=%u: med %.0f min %.0f us (sum=%g)\n", V, P, t[5], t[0], h);
}

int main() {
    const size_t n = 1ull << 26;
    int dev = omp_get_default_device();
    float* in = (float*)omp_target_alloc(n * 4, dev);
    float* part = (float*)omp_target_alloc(1 << 16, dev);
    float* out = (float*)omp_target_alloc(256, dev);
    std::vector<float> h(n, 1.0f); omp_target_memcpy(in, h.data(), n * 4, 0, 0, dev, omp_get_initial_device());
    for (unsigned P : {2048u, 4096u}) { bench<0>(in, part, out, n, P); bench<1>(in, part, out, n, P); bench<2>(in, part, out, n, P); }
}
