#include <chrono>
#include <cstdio>
#include <vector>
#include <algorithm>
#include <thread>
#include <sched.h>
#include "tsr/device/memory.h"
#include "tsr/prims/prims.h"
using clk = std::chrono::steady_clock;
int main() {
    const size_t n = 1ull << 26;
    std::vector<float> h(n, 1.0f);
    tsr::DeviceBuffer<float> d; d.upload(h); tsr::DeviceBuffer<float> o(1);
    tsr::Arena arena(1 << 20);
    float v; int stalls = 0, migrations = 0;
    for (int round = 0; round < 8; ++round) {
        std::vector<double> t;
        for (int r = 0; r < 16; ++r) {
            int c0 = sched_getcpu();
            auto a = clk::now(); arena.reset(); tsr::prims::reduce(d.data(), n, o.data(), tsr::prims::ReduceOp::Sum, arena, nullptr); auto m = clk::now(); o.download(&v, 1); auto b = clk::now();
            int c1 = sched_getcpu();
            double us = std::chrono::duration<double, std::micro>(b - a).count();
            if (c0 != c1) migrations++;
            if (us > 1000) { stalls++; printf("  stall %.0f us (reduce %.0f) cpu %d -> %d\n", us, std::chrono::duration<double, std::micro>(m - a).count(), c0, c1); }
            if (r) t.push_back(us);
        }
        std::sort(t.begin(), t.end());
        printf("round %d: min %.0f med %.0f max %.0f\n", round, t.front(), t[t.size()/2], t.back());
        std::this_thread::sleep_for(std::chrono::milliseconds(300 * round));
    }
    printf("stalls=%d migrations=%d\n", stalls, migrations);
}
EOF
